{
  "rationale": "Gather core company data, recent financials, disclosed risk factors, market sentiment, and peer benchmarks, then compute key margins and growth rates to inform each risk category.",
  "steps": [
    {
      "id": "s1",
      "goal": "Obtain basic company information and fiscal calendar",
      "tool": "company_profile",
      "args": { "ticker": "TSLA" },
      "depends_on": [],
      "reason": "Provides legal name, sector, fiscal year end and key executives needed for context."
    },
    {
      "id": "s2",
      "goal": "Retrieve the latest three years of audited financial statements",
      "tool": "financial_data_api",
      "args": { "ticker": "TSLA", "statement_type": "income_statement", "period": "annual", "years": 3 },
      "depends_on": [],
      "reason": "Full income statements supply revenue, cost of goods sold, operating expenses, and net income for margin and growth calculations."
    },
    {
      "id": "s3",
      "goal": "Extract disclosed risk factors from the most recent Form 10‑K",
      "tool": "sec_filing_search",
      "args": { "ticker": "TSLA", "filing_type": "10-K" },
      "depends_on": [],
      "reason": "Item 1A contains the company's own assessment of financial, operational, regulatory, and competitive risks."
    },
    {
      "id": "s4",
      "goal": "Gauge current market narrative and sentiment around Tesla",
      "tool": "news_sentiment",
      "args": { "query": "Tesla Inc", "num_articles": 20, "lookback_days": 30 },
      "depends_on": [],
      "reason": "Recent news sentiment helps contextualize regulatory and competitive risk exposure."
    },
    {
      "id": "s5",
      "goal": "Compare Tesla to peers on key financial metrics",
      "tool": "peer_comparison",
      "args": {
        "ticker": "TSLA",
        "num_peers": 5,
        "metrics": ["revenue", "revenue_growth", "gross_margin", "operating_margin", "net_margin", "roe", "pe_ratio", "market_cap"]
      },
      "depends_on": [],
      "reason": "Relative performance highlights competitive pressures and market positioning."
    },
    {
      "id": "s6",
      "goal": "Calculate gross, operating, and net margins for FY2025",
      "tool": "calculation_engine",
      "args": {
        "calculation_type": "margin",
        "inputs": {
          "numerator": "gross_profit_FY2025",
          "revenue": "revenue_FY2025"
        }
      },
      "depends_on": ["s2"],
      "reason": "Margins are needed to assess financial health and operational risk."
    },
    {
      "id": "s7",
      "goal": "Compute year‑over‑year revenue growth rate FY2025 vs FY2024",
      "tool": "calculation_engine",
      "args": {
        "calculation_type": "growth_rate",
        "inputs": {
          "current": "revenue_FY2025",
          "previous": "revenue_FY2024"
        }
      },
      "depends_on": ["s2"],
      "reason": "Revenue growth informs financial risk and the ability to fund operations and investments."
    }
  ]
}
